export function v100StoryEventFor(id){return V100_STORY_EVENTS[id]??null;}
export function v100StoryEventIdsForStage(number){const stage=String(Number(number)).padStart(2,'0');return ['pre','post','first-clear-post'].map(phase=>`v100:event:s${stage}:${phase}`).filter(id=>Boolean(V100_STORY_EVENTS[id]));}
export function v100StoryNodeText(node,playerName){return node?.text==null?'':renderV100PlayerName(node.text,playerName);}
export function v100StoryEventView(id,playerName){const event=v100StoryEventFor(id);return event?{...event,nodes:event.nodes.map(node=>({...node,text:v100StoryNodeText(node,playerName)}))}:null;}
export function v100StoryContract(){return Object.freeze({eventIds:V100_EVENT_IDS,eventCount:V100_EVENT_IDS.length,prologueFirst:V100_EVENT_IDS[0],endingSequence:['v100:event:ending','v100:event:credits'],creditsHasDialogue:false,creditsMusic:null,sourceSha256:V100_STORY_SOURCE_SHA256});}
